# K1
#cipher_words = ['89411894', '4254', '7171031', '4502', '971559793', '53177', '636187', '20', '4504', '376', '361', '57643', '85053600', '29', '7004062', '4468', '923921735', '946320122', '930424404', '88527391', '692473', '84524991', '87445918', '638440', '23', '52381']
#cipher_text = ""
# K2
cipher_words = ['55709', '605858', '4045', '341', '945432286', '641971', '7699855', '7954481', '7080686', '7906967', '391', '7614435', '7811539', '7073281', '4530', '338', '59207', '920376451', '21', '20', '52123', '652655', '50461', '308', '89447709', '7756659']
cipher_text = ""
# K3
#cipher_words = ['243255912', '222146337', '946294413', '37638005', '80920926', '63388773', '6103003', '5954191', '2167948', '0273351', '8621836', '871646', '317077', '156978', '444396', '143261', '96972', '79833', '14246', '09525', '0648', '860', '781', '418', '30', '93']
#cipher_text = ""
cipher_list = []

assert(len(cipher_words) == 26)

#
# Break the cipher out into a list of words
#
i = 0
while i < len(cipher_text) - 1:
    for j in range(min(len(cipher_text), i+9), i+1, -1):
        word = cipher_text[i:j]
        if word in cipher_words:
            cipher_list.append(word)
            break
    i = j

print("cipher_list", cipher_list)

#
# Make sure we have a match
#
assert(cipher_text == ''.join(cipher_list))

def doit(cipher):
    state = []
    key = {}
    running_offset = 0            # alphabet offset at the current point in the cipher
    start_offset = running_offset # first offset we tried before moving on to others
    key_offset = 0                # offset to store in the key for the given code word
    previous_word = None

    i = 0
    loop_count = 0   # temp so we can break out of infinite loops

    #
    # Variables to save with state (anything not explicitly set/assigned at start of while loop):
    # running_offset, start_offset, key, previous_word
    #
    while i < len(cipher):
        (cipher_word, plaintext_char) = cipher[i]
        key_char = chr((ord(plaintext_char) - ord('a') + running_offset) % 26 + ord('a'))
        key_offset = (running_offset - start_offset) % 26

        print("word %s cur_char %c key_char %c running_offset %d key_offset %d key" % (cipher_word, plaintext_char, key_char, running_offset, key_offset), key)

        key_ok = True

        if cipher_word in key:
            (ch, of) = key[cipher_word]

            # key collision: key[n] already set to something other than what we are trying to assign
            if ch != key_char:
                print("key collision for '%s': %s != %s" % (cipher_word, key_char, ch))
                key_ok = False
            elif of == None:
                # optimization for the case where we have two consecutive identical code words, which (I
                # think) is the only time the key can exist with a null offset at this point. In that case,
                # the offset has to be whatever difference "fits" the two consecutive plaintext characters
                print("Consecutive word found - assign offset for %s to %d" % (cipher_word, key_offset))
                key[cipher_word] = (ch, key_offset)
            elif of != key_offset:
                print("offset mismatch for '%s': %d != %d" % (cipher_word, of, key_offset))
                key_ok = False

        elif key_char in [a for (a,x) in key.values()]:
            # duplicate key_val: key[a] and key[b] both map to the same letter
            print("duplicate key_val %c (orig %c offset %d)" % (key_char, plaintext_char, running_offset))
            print("key:",key)
            key_ok = False

        else:
            # Key looks good & is not currently in the dictionary, so add it
            key[cipher_word] = (key_char, None)    # We won't know the offset until the next iteration

        if key_ok:
            # Assign the rotation offset for the previous word, if needed
            if previous_word in key:
                (ch, of) = key[previous_word]
                if of == None:
                    print("Assign offset for %s to %d (running_offset %d start_offset %d)" % (previous_word, key_offset, running_offset, start_offset))
                    key[previous_word] = (ch, key_offset)
        else:
            # Should be able to optimize this in cases where the key is already set and we can calculate
            # what the offset would have to be to fit a specific letter
            running_offset = (running_offset + 1) % 26
            if running_offset == start_offset:

                # We have run through all possible offsets for this character without a fit
                print("Exhausted all possible offsets at position %d- backtracking" % i)
                i -= 1
                if i < 0:
                    print("Could not find a fit... giving up")
                    break
                # discard the most recent state and restore the last known "good" state
                state.pop()
                d = state[-1]
                running_offset = d['running_offset']
                start_offset = d['start_offset']
                previous_word = d['previous_word']
                key = d['key']
                loop_count += 1
                if loop_count >= 10:
                    print("Breaking loop")
                    break
            continue

        # falling through here implies that key_ok == True
        state.append({'running_offset': running_offset,
                      'start_offset': start_offset,
                      'previous_word': previous_word,
                      'key': key.copy()})
        print("current state:", state)
        start_offset = running_offset
        previous_word = cipher_word

        i += 1
    print("Final value of i=%d" % i)
    print("Final state:", state)

# Initialize position offsets to zero and create a list of tuples
cipher = list(zip(cipher_list, 'congratulationsyou'))
doit(cipher)
print("cipher",cipher)
